const string &	GetCurrentQuestName() const;
// MT2009_PLUS_QUEST_PCBLOCK_V1 (quest name) (server-patches/questpcblock): an other-PC block runs the
// selected player in the calling quest's flags (pc.getqf/setqf); the old name comes back at its end.
void		M2SetCurrentQuestName(const string & name) { m_stCurQuest = name; }

	// MT2009_PLUS_QUEST_PCBLOCK_V1 (state) (server-patches/questpcblock): what an other-PC block found
	// (character, PC, selected dungeon, NPC, party member) and gives back exactly at its end - a server
	// timer has no character at all; and the selected player's quest name it replaced.
	void		M2ResetOtherPCBlock();
private:
	struct TM2OtherPCBlockState
	{
		LPCHARACTER	pkPrevChar;
		DWORD		dwPrevCharPID;
		bool		bPrevPC;
		DWORD		dwPrevPCID;
		LPDUNGEON	pkPrevDungeon;
		LPCHARACTER	pkPrevNPC;
		LPCHARACTER	pkPrevPartyMember;
		DWORD		dwQuestNamePID;
		string		stPrevQuestName;
	};
	std::vector <TM2OtherPCBlockState>	m_vecM2OtherPCBlockState;
	PC*			m_pOtherPCBlockRootPC;
	std::vector <DWORD>	m_vecPCStack;

old:
void CQuestManager::BeginOtherPCBlock(DWORD pid)
{
	LPCHARACTER ch = GetCurrentCharacterPtr();
	if (NULL == ch)
	{
		sys_err("NULL?");
		return;
	}
	/*
	# 1. current pid = pid0 <- It will be m_pOtherPCBlockRootPC.
	begin_other_pc_block(pid1)
		# 2. current pid = pid1
		begin_other_pc_block(pid2)
			# 3. current_pid = pid2
		end_other_pc_block()
	end_other_pc_block()
	*/
	// when begin_other_pc_block(pid1)
	if (m_vecPCStack.empty())
	{
		m_pOtherPCBlockRootPC = GetCurrentPC();
	}
	m_vecPCStack.emplace_back(GetCurrentCharacterPtr()->GetPlayerID());
	GetPC(pid);
}

void CQuestManager::EndOtherPCBlock()
{
	if (m_vecPCStack.size() == 0)
	{
		sys_err("m_vecPCStack is alread empty. CurrentQuest{Name(%s), State(%s)}", GetCurrentQuestName().c_str(), GetCurrentState()->_title.c_str());
		return;
	}
	DWORD pc = m_vecPCStack.back();
	m_vecPCStack.pop_back();
	GetPC(pc);

	if (m_vecPCStack.empty())
	{
		m_pOtherPCBlockRootPC = NULL;
	}
}

new:
// MT2009_PLUS_QUEST_PCBLOCK_V1 (block) (server-patches/questpcblock): an other-PC block works without a current
// character too - a server timer (dungeon ticks) has none, and the old code only wrote "NULL?" and left every
// player of the loop unselected. The block keeps what it found (character - none in a timer -, PC, selected
// dungeon, NPC, party member) and gives exactly that back at its end; the selected player runs in the calling
// quest's flags (pc.getqf/setqf) and gets his own quest name back. A player who is not online is skipped: the
// block selects nobody (pc.get_player_id() stays the caller's - 0 in a timer), so the quests' usual
// "if pc.get_player_id() == pid" check skips him. quest.begin_other_pc_block returns whether he was selected.
bool CQuestManager::BeginOtherPCBlock(DWORD pid)
{
	/*
	# 1. current pid = pid0 <- It will be m_pOtherPCBlockRootPC.
	begin_other_pc_block(pid1)
		# 2. current pid = pid1
		begin_other_pc_block(pid2)
			# 3. current_pid = pid2
		end_other_pc_block()
	end_other_pc_block()
	*/
	TM2OtherPCBlockState st;
	st.pkPrevChar = m_pCurrentCharacter;
	st.dwPrevCharPID = m_pCurrentCharacter ? m_pCurrentCharacter->GetPlayerID() : 0;
	st.bPrevPC = m_pCurrentPC != NULL;
	st.dwPrevPCID = m_pCurrentPC ? m_pCurrentPC->GetID() : 0;
	st.pkPrevDungeon = m_pSelectedDungeon;
	st.pkPrevNPC = m_pCurrentNPCCharacter;
	st.pkPrevPartyMember = m_pCurrentPartyMember;
	st.dwQuestNamePID = 0;

	// when begin_other_pc_block(pid1)
	if (m_vecPCStack.empty())
	{
		m_pOtherPCBlockRootPC = GetCurrentPC();
	}
	m_vecPCStack.emplace_back(st.dwPrevCharPID);

	const string stQuestName = m_pCurrentPC ? m_pCurrentPC->GetCurrentQuestName() : string();
	bool bSelected = false;
	if (pid && CHARACTER_MANAGER::instance().FindByPID(pid) && GetPC(pid))
	{
		bSelected = true;
		// the dungeon a timer selected (d.select) stays for the block's d.* calls
		m_pSelectedDungeon = st.pkPrevDungeon;
		if (!stQuestName.empty() && m_pCurrentPC->GetCurrentQuestName() != stQuestName)
		{
			st.dwQuestNamePID = pid;
			st.stPrevQuestName = m_pCurrentPC->GetCurrentQuestName();
			m_pCurrentPC->M2SetCurrentQuestName(stQuestName);
		}
	}
	m_vecM2OtherPCBlockState.push_back(st);
	return bSelected;
}

void CQuestManager::EndOtherPCBlock()
{
	if (m_vecPCStack.size() == 0)
	{
		sys_err("m_vecPCStack is alread empty. CurrentQuest{Name(%s), State(%s)}", m_pCurrentPC ? GetCurrentQuestName().c_str() : "", GetCurrentState() ? GetCurrentState()->_title.c_str() : "");
		return;
	}
	DWORD pc = m_vecPCStack.back();
	m_vecPCStack.pop_back();

	if (m_vecM2OtherPCBlockState.empty())
	{
		GetPC(pc);
	}
	else
	{
		const TM2OtherPCBlockState st = m_vecM2OtherPCBlockState.back();
		m_vecM2OtherPCBlockState.pop_back();

		if (st.dwQuestNamePID)
		{
			PCMap::iterator itName = m_mapPC.find(st.dwQuestNamePID);
			if (itName != m_mapPC.end())
				itName->second.M2SetCurrentQuestName(st.stPrevQuestName);
		}

		// the caller left meanwhile: no character, the server's PC (as in a timer) - never a freed pointer
		bool bGone = st.pkPrevChar && CHARACTER_MANAGER::instance().FindByPID(st.dwPrevCharPID) != st.pkPrevChar;
		PCMap::iterator itPC = m_mapPC.find(st.dwPrevPCID);
		if (bGone || (st.bPrevPC && itPC == m_mapPC.end()))
		{
			sys_err("other pc block: the caller (pid %u) is gone", st.dwPrevCharPID ? st.dwPrevCharPID : st.dwPrevPCID);
			m_pCurrentCharacter = NULL;
			m_pCurrentPC = GetPCForce(0);
			m_pCurrentNPCCharacter = NULL;
			m_pCurrentPartyMember = NULL;
		}
		else
		{
			m_pCurrentCharacter = st.pkPrevChar;
			m_pCurrentPC = st.bPrevPC ? &itPC->second : NULL;
			m_pCurrentNPCCharacter = st.pkPrevNPC;
			m_pCurrentPartyMember = st.pkPrevPartyMember;
		}
		m_pSelectedDungeon = st.pkPrevDungeon;
	}

	if (m_vecPCStack.empty())
	{
		m_pOtherPCBlockRootPC = NULL;
	}
}

// MT2009_PLUS_QUEST_PCBLOCK_V1 (reset): a block a quest error left open (no end_other_pc_block) - its players get
// their quest names back and the next server timer starts clean.
void CQuestManager::M2ResetOtherPCBlock()
{
	if (m_vecPCStack.empty() && m_vecM2OtherPCBlockState.empty())
		return;
	sys_err("other pc block left open (%u level(s)) - closed", (unsigned int) m_vecPCStack.size());
	while (!m_vecM2OtherPCBlockState.empty())
	{
		const TM2OtherPCBlockState& st = m_vecM2OtherPCBlockState.back();
		if (st.dwQuestNamePID)
		{
			PCMap::iterator itName = m_mapPC.find(st.dwQuestNamePID);
			if (itName != m_mapPC.end())
				itName->second.M2SetCurrentQuestName(st.stPrevQuestName);
		}
		m_vecM2OtherPCBlockState.pop_back();
	}
	m_vecPCStack.clear();
	m_pOtherPCBlockRootPC = NULL;
}

sys_log(0, "XXX ServerTimer Call NPC %p vnum %u arg %u", GetPCForce(0), npc, arg);
// MT2009_PLUS_QUEST_PCBLOCK_V1 (timer): a timer is never inside another quest's block - one left open by an error is closed
